param($sync)
try {
    $list = @()
    $queried = $false
    try {
        $entities = @(Get-CimInstance -ClassName Win32_PnPEntity -Filter "ConfigManagerErrorCode <> 0 AND ConfigManagerErrorCode <> 22 AND ConfigManagerErrorCode <> 45" -ErrorAction Stop)
        $queried = $true
        $list = @($entities | ForEach-Object {
